const string MIM_VERSION = "1.10.6";
/*
 * ============================================================
 *  Mamba Inventory Manager (MIM)
 *  Space Engineers | Inspiration: Isy's Inventory Manager
 *  Author: mamba
 *
 *   CONTAINER TAGS  (in block name, OR via Custom Data — see below)
 *  [Ore]        all ores
 *  [Ingot]      all ingots
 *  [Component]  all components
 *  [Tool]       hand tools: welder, grinder, drill
 *  [Weapon]     guns, rifles, hand weapons
 *  [Food]       consumables / food
 *  [Bottle]     O2/H2 bottles
 *  [Ammo]       ammo magazines
 *  [Special]    catch-all
 *
 *   SUBTYPE MODIFIERS  (Ore, Ingot, Component only)
 *  [Ore][Iron]        Iron ore only
 *  [Ore][Iron,Nickel] Iron and Nickel ore
 *  [Ore][!Ice]        All ores EXCEPT Ice  (exclusion prefix)
 *  [Ore][+Ice]        Accept Ice; never move it OUT  (fill-only)
 *  Shorthands: [Ice] [+Ice] [Stone] [+Stone] [Gravel] [+Gravel]
 *
 *   CUSTOM DATA MODE  (cleaner block names)
 *  Add [MIM] to a cargo container's NAME as a marker only.
 *  Put all MIM tags in the container's CUSTOM DATA instead:
 *    --- MIM Data Start ---
 *    [Ore][Iron,Nickel]
 *    [LOCK]
 *    --- MIM Data End ---
 *  Old-style name tags always work (backward-compatible fallback).
 *
 *  NOTE: [!Sub]/[+Sub] govern SORT ROUTING only.
 *  Use [LOCK] to fully protect a container from all MIM writes.
 *
 *   BEHAVIOUR TAGS
 *  [LOCK]   cargo: skip entirely; reactor: fill but never drain
 *  [IGNORE] connector: skip this connector + remote grid
 *  [PULL]   local connector: fill remote reactors + pull cargo
 *  [PUSH]   remote connector: same as [PULL] on local side
 *  [AUTOCRAFT=1] / [AUTOCRAFT=0]  per-assembler override of
 *           FORCE_AUTOCRAFTING (name or Custom Data, name wins)
 *
 *   ROLE TAGS (auto-set on PB name)
 *  [MASTER]  manages this + connected SLAVE grids
 *  [SLAVE]   defers to docked MASTER
 *
 *   LCD TAGS
 *  [MIM]           main status + safe zone + reactor levels + autocraft status
 *  [MIM Ore]       ore stock + refinery priority (editable)
 *  [MIM Ingot]     ingot stock
 *  [MIM Comp]      component stock + autocraft (editable) + autocraft status
 *  [MIM Ammo]      ammo stock
 *  [MIM Warning]   all warnings and errors
 *
 *  AUTOCRAFT diagnostics: [MIM] and [MIM Comp] both show a live one-line
 *  status explaining exactly why crafting did or didn't run this cycle
 *  (e.g. "3 assembler(s), none free: 2 busy, 1 [LOCK]"). STATUS command
 *  also prints assembler/Survival Kit counts to Echo.
 *
 *   COMMANDS (run button argument)
 *  SORT   REFUEL   PULL   MASTER   SLAVE
 *  RESET  STATUS   CLEARERRORS   CONVERT   ADDALL   VOID STONE
 *
 *  ADDALL: adds all known craftable items to [MIM Comp] with Mode=HOLD.
 *          Change individual rows to A or P to enable auto-crafting.
 *
 *  VOID STONE: removes all Stone from the grid (respects [LOCK] containers).
 *
 *   PERFORMANCE
 *  Sort runs in batches (SORT_BATCH_SIZE blocks per tick).
 *  Raise RUN_INTERVAL to reduce load on busy servers.
 * ============================================================
 */
// -----------------------------------------------------------
//  USER CONFIGURATION
// -----------------------------------------------------------

// Seconds between full inventory management cycles.
// Configurable via Custom Data: RUN_INTERVAL=30
static double RUN_INTERVAL = 30.0;

// Max blocks checked per sort tick.
// This limits blocks inspected per tick, NOT item moves.
// Lower this if you hit the 50000 instruction limit (try 20).
const int SORT_BATCH_SIZE = 30;

// Max errors kept in persistent log (Storage).
const int MAX_ERROR_LOG = 20;

// ---- LCD font sizes ----------------------------------------
// Set to 0.0 to let MIM auto-size fonts based on LCD dimensions.
// Set a fixed value (e.g. 0.8) to lock all LCDs to that size.
// Per-LCD override: add  fontsize=0.8  in the LCD's Custom Data.
static float LCD_FONT_SIZE = 0.0f;

// Word-wrap column for [MIM Warning] LCD (characters per line).
// Set to 0 to disable wrapping.
static int WARNING_WRAP_COLS = 45;

// ---- Feature toggles --------------------------------------

static bool SORT_INVENTORY    = true;
static bool MANAGE_REFINERIES = true;
static bool MANAGE_ASSEMBLERS = true;

// When true, Survival Kits are treated as assemblers — MIM will drain their output
// and queue blueprints via them. Set false to completely ignore Survival Kits
// (they stay on, output is still drained to cargo if CLEAN_PRODUCTION_BLOCKS=true,
// but MIM never queues crafting jobs in them).
static bool USE_SURVIVALKIT_AS_ASSEMBLER = false;

// When false (default), MIM only queues new crafting jobs on an assembler
// whose queue is completely empty — this avoids ever duplicating an order.
// Problem: if ONE item in the queue is stuck (missing raw materials), the
// queue never empties, and MIM stops crafting EVERYTHING on that assembler
// forever, even unrelated items that have all materials available.
//
// FORCE_AUTOCRAFTING = true allows MIM to keep adding to a non-empty queue.
// Safety: before queueing, MIM checks what's ALREADY in the assembler's
// queue for that specific item (via GetQueue) and only tops up the
// difference to reach Target — items are never double-queued.
//
// Per-block override (takes priority over this global setting):
//   [AUTOCRAFT=1]  force this assembler ON  regardless of this setting
//   [AUTOCRAFT=0]  force this assembler OFF regardless of this setting
// Works in the block's NAME or its CUSTOM DATA (name checked first).
static bool FORCE_AUTOCRAFTING = true;

// Run each subsystem every N full cycles (1 = every cycle).
const int SORT_INVENTORY_EVERY    = 1;
const int MANAGE_REFINERIES_EVERY = 1;
const int MANAGE_ASSEMBLERS_EVERY = 1;
const int MANAGE_REACTORS_EVERY   = 1;

// ---- Container behaviour ----------------------------------

static bool URANIUM_SEPARATE_CONTAINER    = true;
static bool TOOLS_FOOD_BOTTLE_SAME_CARGO  = true;
static bool WEAPONS_AMMO_SAME_CARGO       = true;
static bool INCLUDE_SUBGRIDS              = false;
static bool CLEAN_PRODUCTION_BLOCKS       = true;
static bool AUTO_TAG_CONTAINERS           = true;
static bool USE_SMALL_CARGO_OVERFLOW      = true;
static bool REACTOR_REMOVE_EXCESS         = true;

// ---- Reactor uranium targets (kg) -------------------------
// Configurable via Custom Data: URANIUM_LARGE_GRID_LARGE=2000  etc.

static float URANIUM_LARGE_GRID_LARGE = 2000f;
static float URANIUM_LARGE_GRID_SMALL =  200f;
static float URANIUM_SMALL_GRID_LARGE =   50f;
static float URANIUM_SMALL_GRID_SMALL =    5f;

// ---- Safe Zone ------------------------------------------

// Set to true to automatically keep Safe Zone blocks stocked with Zone Chips.
// MIM will auto-add [LOCK] to Safe Zone block names and fill them to max capacity.
// Zone Chips are sourced from containers with [Zone Chips] or "SafeZone" in their name.
static bool MANAGE_SAFE_ZONE = true;

// ---- Mod item TypeId mappings -----------------------------
//
// If [MIM Warning] reports "Unknown TypeId: MyObjectBuilder_XYZ/SubtypeId",
// add the TypeId here with its correct category so MIM routes it properly.
// Valid categories: Ore  Ingot  Component  Ammo  Tool  Weapon  Food  Bottle  Special
//
// Example — Industrial Overhaul copper ore:
//   { "MyObjectBuilder_CopperOre", "Ore" },
//
static readonly Dictionary<string,string> EXTRA_TYPE_MAPPINGS =
    new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase)
{
    // { "MyObjectBuilder_YourModTypeId", "Category" },
};

// ---- LCD tags ---------------------------------------------

const string TAG_LCD_MAIN     = "[MIM]";
const string TAG_LCD_ORE      = "[MIM Ore]";
const string TAG_LCD_INGOT    = "[MIM Ingot]";
const string TAG_LCD_COMP     = "[MIM Comp]";
const string TAG_LCD_AMMO     = "[MIM Ammo]";
const string TAG_LCD_WARNINGS = "[MIM Warning]";

// ---- Container + behaviour tags ---------------------------

const string TAG_ORE       = "[Ore]";
const string TAG_INGOT     = "[Ingot]";
const string TAG_COMPONENT = "[Component]";
const string TAG_TOOL      = "[Tool]";
const string TAG_WEAPON    = "[Weapon]";
const string TAG_FOOD      = "[Food]";
const string TAG_BOTTLE    = "[Bottle]";
const string TAG_AMMO      = "[Ammo]";
const string TAG_SPECIAL   = "[Special]";
const string TAG_LOCK      = "[LOCK]";
const string TAG_IGNORE    = "[IGNORE]";
const string TAG_PUSH      = "[PUSH]";
const string TAG_PULL      = "[PULL]";
const string TAG_MASTER    = "[MASTER]";
const string TAG_SLAVE     = "[SLAVE]";
const string TAG_ZONE_CHIPS = "[Zone Chips]";
// Marker placed in a container's NAME to signal that MIM tags
// are in its Custom Data instead of the name (Custom Data mode).
const string TAG_MIM_MARKER = "[MIM]";

// ---- MIM Data section delimiters ---------------------------
// Wrap MIM settings in any block's Custom Data with these two lines so MIM
// only reads what's between them — other mods' data, or your own notes,
// anywhere else in the same Custom Data field are left completely alone:
//
//   --- MIM Data Start ---
//   [Ore][Iron,Nickel]
//   [LOCK]
//   --- MIM Data End ---
//
// If no Start marker is found, MIM reads the ENTIRE Custom Data field
// (old behaviour — fully backward compatible with existing setups).
const string MIM_DATA_START = "--- MIM Data Start ---";
const string MIM_DATA_END   = "--- MIM Data End ---";

