eS[0];_freeS.RemoveAt(0);}if (tc==null)return null;string autoTag=BuildAutoClaimTag(cat,sub);tc.CustomName+=autoTag;_autoClaimed[tc]=autoTag;var inv=tc.GetInventory(0);bool isL=IsLargeCargo(tc);if (!_allInvs.Contains(inv))_allInvs.Add(inv);if (sub.Length>0){AddMetaIndex(tc,inv,cat,new List<string>{sub},isL);if (string.Equals(cat,"Ingot",StringComparison.OrdinalIgnoreCase)&&string.Equals(sub,"Uranium",StringComparison.OrdinalIgnoreCase))_catUranium.Add(inv);}else{AddMetaIndex(tc,inv,cat,new List<string>(),isL);AddLegacy(cat,inv);if (string.Equals(cat,"Tool",StringComparison.OrdinalIgnoreCase)&&TOOLS_FOOD_BOTTLE_SAME_CARGO){AddMetaIndex(tc,inv,"Food",new List<string>(),isL);AddLegacy("Food",inv);AddMetaIndex(tc,inv,"Bottle",new List<string>(),isL);AddLegacy("Bottle",inv);}if (string.Equals(cat,"Weapon",StringComparison.OrdinalIgnoreCase)&&WEAPONS_AMMO_SAME_CARGO){AddMetaIndex(tc,inv,"Ammo",new List<string>(),isL);AddLegacy("Ammo",inv);}}return inv;}void AddMetaIndex(IMyTerminalBlock blk,IMyInventory inv,string cat,List<string>ss,bool isL){var m=new ContainerMeta(blk,inv,cat,ss,new List<string>(),new List<string>(),isL);_containers.Add(m);if (!_metaByInv.ContainsKey(inv))_metaByInv[inv]=m;if (!_catContainers.ContainsKey(cat))_catContainers[cat]=new List<ContainerMeta>();_catContainers[cat].Add(m);}void DrainToCategory(IMyInventory src){_tmpItems.Clear();src.GetItems(_tmpItems);for (int i=_tmpItems.Count-1;i>=0;i--)RouteItem(src,_tmpItems[i],ItemCategory(_tmpItems[i].Type),_tmpItems[i].Type.SubtypeId);}void RunRefineryCycle(){var prio=ParseOreConfig();if (prio.Count==0)prio=new Dictionary<string,int>(ORE_DEFAULT_PRIO,StringComparer.OrdinalIgnoreCase);var feedP=new List<int>();var feedT=new List<MyItemType>();for (int i=0;i<ORE_SUBS.Length;i++){int p;if (!prio.TryGetValue(ORE_SUBS[i],out p))if (!ORE_DEFAULT_PRIO.TryGetValue(ORE_SUBS[i],out p))p=5;if (p>0){feedP.Add(p);feedT.Add(ORE_TYPES[i]);}}foreach (var kvp in prio){bool isV=false;for (int i=0;i<ORE_SUBS.Length;i++)if (string.Equals(ORE_SUBS[i],kvp.Key,StringComparison.OrdinalIgnoreCase)){isV=true;break;}if (isV||kvp.Value<=0)continue;feedP.Add(kvp.Value);feedT.Add(new MyItemType("MyObjectBuilder_Ore",kvp.Key));}for (int i=1;i<feedP.Count;i++){int kp=feedP[i];var kt=feedT[i];int j=i-1;while (j>=0&&feedP[j]>kp){feedP[j+1]=feedP[j];feedT[j+1]=feedT[j];j--;}feedP[j+1]=kp;feedT[j+1]=kt;}var oreInvs=new List<IMyInventory>();foreach (var m in _containers)if (m.Category=="Ore")oreInvs.Add(m.Inv);foreach (var r in _refineries){if (Runtime.CurrentInstructionCount>=INSTR_LIMIT)break;if (!r.IsFunctional||HasTag(r.CustomName,TAG_LOCK)||!_managed.Contains(r.CubeGrid))continue;var allowList=ParseRefineryAllow(r);var inp=r.GetInventory(0);var out_=r.GetInventory(1);if (inp==null)continue;float fill=(float)inp.CurrentVolume/(float)inp.MaxVolume;if (fill<0.5f&&oreInvs.Count>0){for (int i=0;i<feedT.Count;i++){if (inp.IsFull)break;if (allowList!=null&&allowList.Count>0){if (!allowList.Contains(feedT[i].SubtypeId))continue;}float avail=SumInvs(feedT[i],oreInvs);if (avail<1f)continue;PullFromAll(feedT[i],Math.Min(avail,500f),inp);}}if (out_!=null&&CLEAN_PRODUCTION_BLOCKS)DrainToCategory(out_);}}HashSet<string>ParseRefineryAllow(IMyRefinery r){string cd=r.CustomData;if (string.IsNullOrEmpty(cd))return null;string section=ExtractMimSection(cd);foreach (var rl in section.Split('\n')){string key,val;if (TryParseKeyValue(rl,out key,out val)&&key=="allow"){var result=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach (var ore in val.Split(',')){string trimmed=ore.Trim();if (trimmed.Length>0)result.Add(trimmed);}return result.Count>0?result:null;}}return null;}void RunAssemblerCycle(){_craftQueued=0;foreach (var a in _assemblers){if (!a.IsFunctional||a.InventoryCount<2||!_managed.Contains(a.CubeGrid))continue;var out_=a.GetInventory(1);if (out_!=null&&CLEAN_PRODUCTION_BLOCKS)DrainToCategory(out_);}if (CLEAN_PRODUCTION_BLOCKS){foreach (var sk in _survivalKits){if (!sk.IsFunctional||sk.InventoryCo