if (inv.TransferItemTo(dest,item,(MyFixedPoint)mv)){excess-=mv;_reactorActs++;break;}}}}}}void RunConnectorCycle(){_pullMoves=0;foreach (var conn in _connectors){if (conn.CustomName.Contains(TAG_IGNORE))continue;if (conn.Status!=MyShipConnectorStatus.Connected)continue;var oth=conn.OtherConnector;if (oth==null||oth.CustomName.Contains(TAG_IGNORE))continue;bool ip=conn.CustomName.Contains(TAG_PULL)||oth.CustomName.Contains(TAG_PUSH);if (ip)PullFromGrid(oth.CubeGrid);}}void PullFromGrid(IMyCubeGrid rg){foreach (var rx in _reactors){if (rx.CubeGrid!=rg||!rx.IsFunctional)continue;var inv=rx.GetInventory(0);if (inv==null)continue;float tgt=ReactorTarget(rx.BlockDefinition.SubtypeId);if (tgt<0f)continue;float cur=(float)inv.GetItemAmount(_uIngot);if (cur<tgt)PullFromAll(_uIngot,tgt-cur,inv);}foreach (var b in _allBlocks){if (b.CubeGrid!=rg||!b.IsFunctional||b.InventoryCount==0)continue;if (HasTag(b.CustomName,TAG_LOCK)||b is IMyReactor)continue;for (int slot=0;slot<b.InventoryCount;slot++){var inv=b.GetInventory(slot);if (inv==null)continue;var items=new List<MyInventoryItem>();inv.GetItems(items);for (int i=items.Count-1;i>=0;i--)if (RouteItem(inv,items[i],ItemCategory(items[i].Type),items[i].Type.SubtypeId))_pullMoves++;}}}Dictionary<string,CraftEntry>ParseCompConfig(){var result=new Dictionary<string,CraftEntry>(StringComparer.OrdinalIgnoreCase);string raw=ReadLCD(TAG_LCD_COMP);if (string.IsNullOrWhiteSpace(raw))return result;foreach (var rl in raw.Split('\n')){string l=rl.Trim();if (!IsDataLine(l))continue;int pipes=0;foreach (char c in l)if (c=='|')pipes++;if (pipes<3)continue;var parts=l.Split('|');if (parts.Length<4)continue;string name=parts[0].Trim();if (string.IsNullOrWhiteSpace(name))continue;string tgtS=parts[2].Trim();string mode=parts[3].Trim().ToUpperInvariant();int sp=mode.IndexOf(' ');if (sp>0)mode=mode.Substring(0,sp).Trim();if (mode!="A"&&mode!="P"&&mode!="OFF"&&mode!="HOLD")continue;int tgt=0;int.TryParse(tgtS,out tgt);result[name]=new CraftEntry(tgt,mode);}return result;}Dictionary<string,int>ParseOreConfig(){var result=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);string raw=ReadLCD(TAG_LCD_ORE);if (string.IsNullOrWhiteSpace(raw))return result;foreach (var rl in raw.Split('\n')){string l=rl.Trim();if (!IsDataLine(l))continue;int pipes=0;foreach (char c in l)if (c=='|')pipes++;if (pipes<2)continue;var parts=l.Split('|');if (parts.Length<3)continue;string name=parts[0].Trim();if (string.IsNullOrWhiteSpace(name))continue;string pri=parts[2].Trim().ToUpperInvariant();if (pri=="OFF"){result[name]=0;continue;}int p;if (!int.TryParse(pri,out p))continue;p=Math.Max(1,Math.Min(9,p));result[name]=p;}return result;}void InitCompLCD(){if (ReadLCD(TAG_LCD_COMP).Contains(LCD_SIG_COMP))return;var sb=new System.Text.StringBuilder();sb.AppendLine(LCD_SIG_COMP);sb.AppendLine("=== MIM - COMPONENT MANAGER ================================");sb.AppendLine("= A=AutoCraft  P=Priority  HOLD/OFF=Track only             =");sb.AppendLine("= !! empty  < below target  = at/above target               =");sb.AppendLine("= CustomData: filter=Motor,Computer  (filter rows)          =");sb.AppendLine("============================================================");sb.AppendLine("Item                 |  Stock | Target |  Mode");sb.AppendLine("----------------------------------------------------");for (int i=0;i<COMP_SUBTYPES.Length;i++){var type=new MyItemType("MyObjectBuilder_Component",COMP_SUBTYPES[i]);int stock=(int)SumAll(type);sb.AppendLine(PadR(COMP_SUBTYPES[i],20)+" | "+PadL(stock.ToString(),6)+" | "+PadL(stock.ToString(),6)+" |  HOLD");}WriteLCDs(TAG_LCD_COMP,sb.ToString());}void InitOreLCD(){if (ReadLCD(TAG_LCD_ORE).Contains(LCD_SIG_ORE))return;var sb=new System.Text.StringBuilder();sb.AppendLine(LCD_SIG_ORE);sb.AppendLine("=== MIM - ORE MANAGER ======================================");sb.AppendLine("= 1-9=Priority (1=highest)  OFF=Skip refinery feed         =");sb.AppendLine("= New ores are added automatically when detected.           =");sb.AppendLine("============================================================");sb.AppendLine("Item              |       Stock | Priority");sb.AppendLine("-------------------------------------------");for (int i=0;i<ORE_SUBS.Length;i++){float stock=(float)SumAll(ORE_TYPES[i]);int p;if (!ORE_DEFAULT_PRIO.TryGetValue(ORE_SUBS[i],out p))p=5;sb.AppendLine(PadR(ORE_SUBS[i],17)+" | "+PadL(FmtKg(stock),10)+" | "+PadL(p==9?"OFF":p.ToString(),8));}WriteLCDs(TAG_LCD_ORE,sb.ToString());}void UpdateAllLCDs(){WriteLCDs(TAG_LCD_MAIN,BuildMain());WriteLCDs(TAG_LCD_INGOT,BuildIngot());WriteLCDs(TAG_LCD_AMMO,BuildAmmo());RefreshCompLCD();RefreshOreLCD();}void UpdateMainLCDOnly(){WriteLCDs(TAG_LCD_MAIN,BuildMain());}void RefreshCompLCD(){var cfg=ParseCompConfig();if (cfg.Count==0)return;var keys=new List<string>(cfg.Keys);keys.Sort((a,b)=>string.Compare(b,a,StringComparison.OrdinalIgnoreCase));var sb=new System.Text.StringBuilder();sb.AppendLine(LCD_SIG_COMP);sb.AppendLine("=== MIM - COMPONENT MANAGER ================================");sb.AppendLine("= A=AutoCraft  P=Priority  HOLD/OFF=Track only             =");sb.AppendLine("= !! empty  < below target  = at/above target               =");sb.AppendLine("============================================================");sb.AppendLine("Item                 |  Stock | Target |  Mode");sb.AppendLine("----------------------------------------------------");foreach (string key in keys){CraftEntry ce=cfg[key];MyItemType type;if (!_knownCompTypes.TryGetValue(key,out type))type=new MyItemType("MyObjectBuilder_Component",key);int stock=(int)SumAll(type);string flag="";if (ce.Mode=="A"||ce.Mode=="P")flag=(stock==0)?" !!":(stock<ce.Target)?"  <":"  =";sb.AppendLine(PadR(key,20)+" | "+PadL(stock.ToString(),6)+" | "+PadL(ce.Target.ToString(),6)+" | "+PadR(ce.Mode,4)+flag);}sb.AppendLine("----------------------------------------------------");sb.AppendLine("Autocraft: "+Trunc(_asmStatus,42));sb.AppendLine("MIM | "+_lastRun.ToString("HH:mm:ss")+" | #"+_cycle);WriteLCDs(TAG_LCD_COMP,sb.ToString());}void RefreshOreLCD(){var prio=ParseOreConfig();var sb=new System.Text.StringBuilder();sb.AppendLine(LCD_SIG_ORE);sb.AppendLine("=== MIM - ORE MANAGER ======================================");sb.AppendLine("= 1-9=Priority (1=highest)  OFF=Skip refinery feed         =");sb.AppendLine("= New ores are added automatically when detected.           =");sb.AppendLine("============================================================");sb.AppendLine("Item              |       Stock | Priority");sb.AppendLine("-------------------------------------------");for (int i=0;i<ORE_SUBS.Length;i++){float stock=(float)SumAll(ORE_TYPES[i]);int p;if (!prio.TryGetValue(ORE_SUBS[i],out p))if (!ORE_DEFAULT_PRIO.TryGetValue(ORE_SUBS[i],out p))p=5;sb.AppendLine(PadR(ORE_SUBS[i],17)+" | "+PadL(FmtKg(stock),10)+" | "+PadL(p==0?"OFF":p.ToString(),8));}foreach (var kvp in prio){bool isV=false;for (int i=0;i<ORE_SUBS.Length;i++)if (string.Equals(ORE_SUBS[i],kvp.Key,StringComparison.OrdinalIgnoreCase)){isV=true;break;}if (isV)continue;float stock=(float)SumAll(new MyItemType("MyObjectBuilder_Ore",kvp.Key));sb.AppendLine(PadR(kvp.Key,17)+" | "+PadL(FmtKg(stock),10)+" | "+PadL(kvp.Value==0?"OFF":kvp.Value.ToString(),8));}sb.AppendLine("-------------------------------------------");sb.AppendLine("MIM | "+_lastRun.ToString("HH:mm:ss")+" | #"+_cycle);WriteLCDs(TAG_LCD_ORE,sb.ToString());}string BuildMain(){string role=_isMaster?"MASTER":(_slaveStop?"SLAVE-idle":"SLAVE-local");int gen=0,sub=0;foreach (var m in _containers){if (m.Subtypes.Count>0)sub++;else gen++;}var sb=new System.Text.StringBuilder();sb.AppendLine("=== MIM v"+MIM_VERSION+" ["+role+"] ===");sb.AppendLine(_lastRun.ToString("HH:mm:ss")+" | Cycle #"+_cycle);sb.AppendLine(_status);sb.AppendLine("Phase: "+_phase+"/8 - "+PHASE_NAMES[_phase%PHASE_COUNT]);if (_slaveStop){sb.AppendLine("Master: "+_masterName);}else{sb.AppendLine("---");sb.AppendLine("Interval: "+RUN_INTERVAL.ToString("F0")+"s  Next in: "+Math.Max(0,RUN_INTERVAL-_elapsed).ToString("F0")+"s");sb.AppendLine("Containers: gen="+gen+" sub="+sub);sb.AppendLine("Free: L="+_freeL.Count+" S="+_freeS.Count);sb.AppendLine("Managed grids: "+_managed.Count);sb.AppendLine("Sort/Ref/Asm every: "+SORT_INVENTORY_EVERY+"/"+MANAGE_REFINERIES_EVERY+"/"+MANAGE_ASSEMBLERS_EVERY+" cycles");sb.AppendLine("Sort batch: "+SORT_BATCH_SIZE+" blk | "+_sortIdx+"/"+_allBlocks.Count);sb.AppendLine("---");sb.AppendLine("Sort:"+_sortMoves+" Craft:"+_craftQueued+" Rx:"+_reactorActs+" Pull:"+_pullMoves);if (_convFail>0)sb.AppendLine("!! Conveyor fail: "+_convFail);sb.AppendLine("---");sb.AppendLine("Instr/phase (limit="+INSTR_LIMIT+"):");for (int pi=0;pi<PHASE_COUNT;pi++){if (_phaseInstr[pi]>0)sb.AppendLine("  Ph"+pi+": "+_phaseInstr[pi]+(_phaseInstr[pi]>INSTR_LIMIT?" <!OVER!>":""));}sb.AppendLine("Total last tick: "+Runtime.CurrentInstructionCount);}AppendSafeZones(sb);AppendReactors(sb);AppendAutocraft(sb);sb.AppendLine("---");int total=_warnings.Count+_errorLog.Count;sb.AppendLine("ERRORS:");if (total==0)sb.AppendLine("  no errors");else{if (_warnings.Count>0)sb.AppendLine("  "+_warnings.Count+" warning(s)");if (_errorLog.Count>0)sb.AppendLine("  "+_errorLog.Count+" error(s)");sb.AppendLine("  See [MIM Warning]");if (_errorLog.Count>0)sb.AppendLine("  Type CLEARERRORS to dismiss");}return sb.ToString();}void AppendReactors(System.Text.StringBuilder sb){sb.AppendLine("REACTORS:");bool any=false;foreach (var r in _reactors){if (!r.IsFunctional||r.CubeGrid!=Me.CubeGrid)continue;any=true;float tgt=ReactorTarget(r.BlockDefinition.SubtypeId);var inv=r.GetInventory(0);float cur=inv!=null?(float)inv.GetItemAmount(_uIngot):0f;bool locked=HasTag(r.CustomName,TAG_LOCK);string name=Trunc(r.CustomName,16)+(locked?"[L]":"");if (tgt>=0f){float pct=tgt>0?cur/tgt*100f:0f;sb.AppendLine("  "+name);sb.AppendLine("  ["+ProgBar(pct,12)+"]"+cur.ToString("F0")+"/"+tgt.ToString("F0")+"kg");}else{sb.AppendLine("  "+name+" [?]");sb.AppendLine("  U: "+cur.ToString("F1")+"kg (unknown type)");}}if (!any)sb.AppendLine("  (none on this grid)");}void AppendAutocraft(System.Text.StringBuilder sb){if (!MANAGE_ASSEMBLERS)return;sb.AppendLine("AUTOCRAFT:");sb.AppendLine("  "+Trunc(_asmStatus,52));}void AppendSafeZones(System.Text.StringBuilder sb){if (!MANAGE_SAFE_ZONE||_safeZones.Count==0)return;sb.AppendLine("SAFE ZONES:");foreach (var sz in _safeZones){if (sz.CubeGrid!=Me.CubeGrid)continue;string name=Trunc(sz.CustomName,18);if (!sz.IsFunctional){sb.AppendLine("  "+name);sb.AppendLine("  [INACTIVE]");continue;}var inv=sz.GetInventory(0);float cur=inv!=null?(float)inv.GetItemAmount(_zoneChip):0f;float maxChips=inv!=null?(float)inv.MaxVolume/0.0005f:0f;float pct=maxChips>0?cur/maxChips*100f:0f;sb.AppendLine("  "+name);sb.AppendLine("  ["+ProgBar(pct,12)+"]"+(int)cur+"/"+(int)maxChips);}float stored=0f;foreach (var inv in _zoneChipInvs)stored+=(float)inv.GetItemAmount(_zoneChip);sb.AppendLine("  Stock: "+(int)stored+" chips");}string BuildIngot(){var sb=new System.Text.StringBuilder();sb.AppendLine("=== MIM - INGOT INVENTORY ===");for (int i=0;i<INGOT_LABELS.Length;i++){float a=(float)SumAll(INGOT_TYPES[i]);if (a<0.01f)continue;sb.AppendLine(PadR(INGOT_LABELS[i],14)+" "+PadL(FmtKg(a),12));}sb.AppendLine("MIM | "+_lastRun.ToString("HH:mm:ss"));return sb.ToString();}string BuildAmmo(){var sb=new System.Text.StringBuilder();sb.AppendLine("=== MIM - AMMO INVENTORY ===");string[]subs={"NATO_5p56x45mm","NATO_25x184mm","Missile200mm","LargeCalibreAmmo","MediumCalibreAmmo","SmallCalibreAmmo","LargeRailgunAmmo","SmallRailgunAmmo","AutocannonClip"};foreach (var s in subs){float a=(float)SumAll(new MyItemType("MyObjectBuilder_AmmoMagazine",s));if (a<0.5f)continue;sb.AppendLine(PadR(Trunc(s,22),22)+" "+PadL(((int)a).ToString(),5));}sb.AppendLine("MIM | "+_lastRun.ToString("HH:mm:ss"));return sb.ToString();}void WritePBScreen(){IMyTextSurface surf=Me.GetSurface(0);if (surf==null)return;bool hasErr=_errorLog.Count>0||_status.StartsWith("ERR");bool hasWarn=_warnings.Count>0;surf.ContentType=VRage.Game.GUI.TextPanel.ContentType.TEXT_AND_IMAGE;surf.Font="Monospace";surf.TextPadding=2f;if (hasErr){surf.FontColor=new Color(255,60,60);surf.BackgroundColor=new Color(40,0,0);}else if (hasWarn){surf.FontColor=new Color(255,200,0);surf.BackgroundColor=new Color(30,20,0);}else{surf.FontColor=new Color(60,255,100);surf.BackgroundColor=new Color(0,18,0);}string role=_isMaster?"MASTER":(_slaveStop?"SLAVE-idle":"SLAVE");var sb=new System.Text.StringBuilder();sb.AppendLine("/usr/MIM/v"+MIM_VERSION);sb.AppendLine("$ ./mim --role="+role+" --grid=\""+Trunc(Me.CubeGrid.CustomName,16)+"\"");sb.AppendLine(new string ('-',22));sb.Append(BuildMain());string pbText=sb.ToString();surf.FontSize=AutoFontSize(surf,CountLines(pbText),Me.CustomData);surf.WriteText(pbText);}void UpdateWarningsLCD(){var sb=new System.Text.StringBuilder();sb.AppendLine("=== MIM v"+MIM_VERSION+" - WARNINGS ===");sb.AppendLine(_lastRun.ToString("HH:mm:ss")+" | Cycle #"+_cycle);sb.AppendLine(new string ('-',38));bool any=false;if (_warnings.Count>0){sb.AppendLine("-- Cycle warnings ("+_warnings.Count+") --");for (int i=0;i<_warnings.Count;i++){string line=(i+1)+". "+_warnings[i];sb.AppendLine(WARNING_WRAP_COLS>0?WordWrap(line,WARNING_WRAP_COLS,"   "):line);}any=true;}if (_errorLog.Count>0){sb.AppendLine("-- Persistent errors ("+_errorLog.Count+") -- CLEARERRORS to dismiss");for (int i=0;i<_errorLog.Count;i++){string line=(i+1)+". "+_errorLog[i];sb.AppendLine(WARNING_WRAP_COLS>0?WordWrap(line,WARNING_WRAP_COLS,"   "):line);}any=true;}if (!any)sb.AppendLine("No warnings.");WriteLCDs(TAG_LCD_WARNINGS,sb.ToString());}string WordWrap(string text,int cols,string indent){if (text.Length<=cols)return text;var sb=new System.Text.StringBuilder();int pos=0;bool first=true;while (pos<text.Length){string prefix=first?"":indent;first=false;int avail=cols-prefix.Length;if (avail<=0)avail=cols;int take=Math.Min(avail,text.Length-pos);if (pos+take<text.Length){int sp=text.LastIndexOf(' ',pos+take-1,take);if (sp>pos)take=sp-pos+1;}sb.AppendLine(prefix+text.Substring(pos,take).TrimEnd());pos+=take;while (pos<text.Length&&text[pos]==' ')pos++;}return sb.ToString().TrimEnd();}void WriteLCDs(string tag,string text){List<IMyTextPanel>list;if (!_lcdCache.TryGetValue(tag,out list)){list=new List<IMyTextPanel>();GridTerminalSystem.GetBlocksOfType<IMyTextPanel>(list,p=>p.CustomName.Contains(tag));}int lines=CountLines(text);foreach (var lcd in list){string filter=GetFilter(lcd);string finalText=filter.Length>0?ApplyFilter(text,filter,tag):text;int finalLines=filter.Length>0?CountLines(finalText):lines;lcd.ContentType=VRage.Game.GUI.TextPanel.ContentType.TEXT_AND_IMAGE;lcd.Font="Monospace";lcd.FontSize=AutoFontSize(lcd,finalLines,lcd.CustomData);lcd.WriteText(finalText);}}int CountLines(string s){int n=1;foreach (char c in s)if (c=='\n')n++;return n;}string ReadLCD(string tag){List<IMyTextPanel>list;if (_lcdCache.TryGetValue(tag,out list)&&list.Count>0)return list[0].GetText();var lcds=new List<IMyTextPanel>();GridTerminalSystem.GetBlocksOfType<IMyTextPanel>(lcds,p=>p.CustomName.Contains(tag));return lcds.Count>0?lcds[0].GetText():"";}float AutoFontSize(IMyTextSurface s,int lineCount,string customData){if (!string.IsNullOrWhiteSpace(customData)){string section=ExtractMimSection(customData);foreach (var rl in section.Split('\n')){string key,val;if (TryParseKeyValue(rl,out key,out val)&&key=="fontsize"){float fv;if (float.TryParse(val,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out fv)&&fv>0f)return Math.Max(0.3f,Math.Min(10f,fv));}}}if (LCD_FONT_SIZE>0f)return LCD_FONT_SIZE;Vector2 tex=s.TextureSize;float w=tex.X>1f?tex.X:s.SurfaceSize.X;if (w<=1f)return 0.75f;float baseFont=w/680f;if (lineCount>0){float h=tex.Y>1f?tex.Y:s.SurfaceSize.Y;float maxFont=(h*0.90f)/(lineCount*26f);baseFont=Math.Min(baseFont,maxFont);}return Math.Max(0.45f,Math.Min(1.5f,baseFont));}string GetFilter(IMyTextPanel lcd){string cd=lcd.CustomData;if (string.IsNullOrWhiteSpace(cd))return "";string section=ExtractMimSection(cd);foreach (var rl in section.Split('\n')){string key,val;if (TryParseKeyValue(rl,out key,out val)&&key=="filter")return val;}return "";}bool TryParseKeyValue(string line,out string key,out string val){key="";val="";if (string.IsNullOrEmpty(line))return false;line=line.Trim();int sep=line.IndexOfAny(new char[]{'=',':'});if (sep<=0)return false;key=line.Substring(0,sep).Trim().ToLower();val=line.Substring(sep+1).Trim();return key.Length>0;}string ApplyFilter(string content,string filterStr,string lcdTag){string[]filters=filterStr.Split(',');for (int i=0;i<filters.Length;i++)filters[i]=filters[i].Trim();var lines=content.Split('\n');var sb=new System.Text.StringBuilder();bool titleDone=false;foreach (var raw in lines){string l=raw.TrimEnd();if (!titleDone&&l.Length>0){sb.AppendLine(l+" [~"+filterStr+"~]");titleDone=true;continue;}bool structural=(l.Length==0||!IsDataLine(l)||l.StartsWith("MIM ")||l.StartsWith("Item "));if (structural){sb.AppendLine(l);continue;}foreach (var f in filters){if (f.Length>0&&l.IndexOf(f,StringComparison.OrdinalIgnoreCase)>=0){sb.AppendLine(l);break;}}}return sb.ToString();}float PullFromAll(MyItemType type,float needed,IMyInventory dest){float rem=needed;foreach (var src in _allInvs){if (rem<=0.01f)break;if (src==dest||_lockedInvs.Contains(src))continue;if ((float)src.GetItemAmount(type)<=0.01f)continue;var items=new List<MyInventoryItem>();src.GetItems(items,it=>it.Type==type);foreach (var item in items){if (rem<=0.01f)break;float mv=Math.Min(rem,(float)item.Amount);if (src.TransferItemTo(dest,item,(MyFixedPoint)mv))rem-=mv;}}return needed-rem;}float PushToList(MyItemType type,float excess,IMyInventory src,List<IMyInventory>dests){float rem=excess;var items=new List<MyInventoryItem>();src.GetItems(items,it=>it.Type==type);foreach (var item in items){if (rem<=0.01f)break;foreach (var d in dests){if (d.IsFull||_lockedInvs.Contains(d))continue;float mv=Math.Min(rem,(float)item.Amount);if (src.TransferItemTo(d,item,(MyFixedPoint)mv)){rem-=mv;break;}}}return excess-rem;}float SumInvs(MyItemType type,List<IMyInventory>invs){float t=0f;foreach (var i in invs)t+=(float)i.GetItemAmount(type);return t;}VRage.MyFixedPoint SumAll(MyItemType type){VRage.MyFixedPoint t=0;foreach (var i in _allInvs)t+=i.GetItemAmount(type);return t;}string ProgBar(float pct,int w){int f=Math.Max(0,Math.Min(w,(int)Math.Round(pct/100f*w)));return new string ('#',f)+new string ('.',w-f);}string FmtKg(float kg){if (kg>=1000000f)return (kg/1000000f).ToString("F2")+"M kg";if (kg>=1000f)return (kg/1000f).ToString("F1")+"k kg";return ((int)kg).ToString()+" kg";}string Trunc(string s,int max){return s.Length<=max?s:s.Substring(0,max-2)+"..";}string PadR(string s,int len){if (s.Length>=len)return s.Substring(0,len);return s+new string (' ',len-s.Length);}string PadL(string s,int len){if (s.Length>=len)return s.Substring(0,len);return new string (' ',len-s.Length)+s;}bool HasTag(string name,string tag){return name.IndexOf(tag,StringComparison.OrdinalIgnoreCase)>=0;}string ExtractMimSection(string customData){if (string.IsNullOrEmpty(customData))return customData;int s=customData.IndexOf(MIM_DATA_START,StringComparison.OrdinalIgnoreCase);if (s<0)return customData;s+=MIM_DATA_START.Length;int e=customData.IndexOf(MIM_DATA_END,s,StringComparison.OrdinalIgnoreCase);return e>s?customData.Substring(s,e-s):customData.Substring(s);}int AutocraftOverride(IMyTerminalBlock b){int v=ParseAutocraftTag(b.CustomName);if (v>=0)return v;string section=ExtractMimSection(b.CustomData);return ParseAutocraftTag(section);}int ParseAutocraftTag(string src){if (string.IsNullOrEmpty(src))return-1;int idx=src.IndexOf("[AUTOCRAFT=",StringComparison.OrdinalIgnoreCase);if (idx<0)return-1;int start=idx+11;int end=src.IndexOf(']',start);if (end<0||end<=start)return-1;string val=src.Substring(start,end-start).Trim();if (val=="1")return 1;if (val=="0")return 0;return-1;}int QueuedAmount(IMyAssembler a,string sub){string bp=sub;for (int i=0;i<COMP_SUBTYPES.Length;i++)if (string.Equals(COMP_SUBTYPES[i],sub,StringComparison.OrdinalIgnoreCase)){bp=COMP_BLUEPRINTS[i];break;}var queue=new List<MyProductionItem>();a.GetQueue(queue);int total=0;foreach (var qi in queue){string sid=qi.BlueprintId.SubtypeName;if (string.Equals(sid,bp,StringComparison.OrdinalIgnoreCase)||string.Equals(sid,sub,StringComparison.OrdinalIgnoreCase)||string.Equals(sid,sub+"Component",StringComparison.OrdinalIgnoreCase))total+=(int)qi.Amount;}return total;}void PrintDetailedStatus(){string role=_isMaster?"MASTER":(_slaveStop?"SLAVE-idle":"SLAVE");int gen=0,sub=0;foreach (var m in _containers){if (m.Subtypes.Count>0)sub++;else gen++;}Echo("=== MIM "+MIM_VERSION+" ["+role+"] ===");Echo("Cycle #"+_cycle+" Ph"+_phase+"/8: "+PHASE_NAMES[_phase%PHASE_COUNT]);Echo("Interval: "+RUN_INTERVAL+"s  Next: "+Math.Max(0,RUN_INTERVAL-_elapsed).ToString("F0")+"s");Echo("Sort batch: "+SORT_BATCH_SIZE+" | cursor: "+_sortIdx+"/"+_allBlocks.Count);Echo("Sort/Ref/Asm every: "+SORT_INVENTORY_EVERY+"/"+MANAGE_REFINERIES_EVERY+"/"+MANAGE_ASSEMBLERS_EVERY+" cycles");Echo("Managed grids: "+_managed.Count+" | Containers: gen="+gen+" sub="+sub);Echo("All invs: "+_allInvs.Count+" | Locked: "+_lockedInvs.Count);Echo("Free L="+_freeL.Count+" S="+_freeS.Count);Echo("Sort:"+_sortMoves+" Craft:"+_craftQueued+" Rx:"+_reactorActs+" Pull:"+_pullMoves+" CF:"+_convFail);Echo("Warnings: "+_warnings.Count+" | Errors: "+_errorLog.Count);Echo("Status: "+_status);Echo("Autocraft: "+_asmStatus);Echo("Assemblers: "+_assemblers.Count+" | SurvivalKits: "+_survivalKits.Count+" (USE_SURVIVALKIT_AS_ASSEMBLER="+USE_SURVIVALKIT_AS_ASSEMBLER+")");Echo("Non-conveyor blocks detected: "+_nonConveyorBlocks.Count);}void ApplyGlobalConfig(){string cd=Me.CustomData;bool hasSection=cd.IndexOf(MIM_DATA_START,StringComparison.OrdinalIgnoreCase)>=0;if (!hasSection){string template=GenerateMimConfigTemplate();Me.CustomData=string.IsNullOrEmpty(cd)?template:cd+"\n\n"+template;return;}string section=ExtractMimSection(cd);foreach (var rl in section.Split('\n')){string key,val;if (!TryParseKeyValue(rl,out key,out val))continue;try{switch (key){case "run_interval":double d;if (double.TryParse(val,out d)&&d>0)RUN_INTERVAL=d;break;case "lcd_font_size":float f;if (float.TryParse(val,out f))LCD_FONT_SIZE=f;break;case "warning_wrap_cols":int i;if (int.TryParse(val,out i))WARNING_WRAP_COLS=i;break;case "sort_inventory":bool b;if (bool.TryParse(val,out b))SORT_INVENTORY=b;break;case "manage_refineries":if (bool.TryParse(val,out b))MANAGE_REFINERIES=b;break;case "manage_assemblers":if (bool.TryParse(val,out b))MANAGE_ASSEMBLERS=b;break;case "use_survivalkit_as_assembler":if (bool.TryParse(val,out b))USE_SURVIVALKIT_AS_ASSEMBLER=b;break;case "force_autocrafting":if (bool.TryParse(val,out b))FORCE_AUTOCRAFTING=b;break;case "uranium_separate_container":if (bool.TryParse(val,out b))URANIUM_SEPARATE_CONTAINER=b;break;case "tools_food_bottle_same_cargo":if (bool.TryParse(val,out b))TOOLS_FOOD_BOTTLE_SAME_CARGO=b;break;case "weapons_ammo_same_cargo":if (bool.TryParse(val,out b))WEAPONS_AMMO_SAME_CARGO=b;break;case "include_subgrids":if (bool.TryParse(val,out b))INCLUDE_SUBGRIDS=b;break;case "clean_production_blocks":if (bool.TryParse(val,out b))CLEAN_PRODUCTION_BLOCKS=b;break;case "auto_tag_containers":if (bool.TryParse(val,out b))AUTO_TAG_CONTAINERS=b;break;case "use_small_cargo_overflow":if (bool.TryParse(val,out b))USE_SMALL_CARGO_OVERFLOW=b;break;case "reactor_remove_excess":if (bool.TryParse(val,out b))REACTOR_REMOVE_EXCESS=b;break;case "manage_safe_zone":if (bool.TryParse(val,out b))MANAGE_SAFE_ZONE=b;break;case "uranium_large_grid_large":if (float.TryParse(val,out f))URANIUM_LARGE_GRID_LARGE=f;break;case "uranium_large_grid_small":if (float.TryParse(val,out f))URANIUM_LARGE_GRID_SMALL=f;break;case "uranium_small_grid_large":if (float.TryParse(val,out f))URANIUM_SMALL_GRID_LARGE=f;break;case "uranium_small_grid_small":if (float.TryParse(val,out f))URANIUM_SMALL_GRID_SMALL=f;break;}}catch{}}}string GenerateMimConfigTemplate(){var sb=new System.Text.StringBuilder();sb.AppendLine(MIM_DATA_START);sb.AppendLine("// MIM Configuration - edit values below");sb.AppendLine("// Lines starting with // are comments");sb.AppendLine();sb.AppendLine("// Cycle interval in seconds (higher = less CPU)");sb.AppendLine("RUN_INTERVAL = "+RUN_INTERVAL);sb.AppendLine();sb.AppendLine("// LCD font size (0 = auto-size, or fixed value like 0.8)");sb.AppendLine("LCD_FONT_SIZE = "+LCD_FONT_SIZE);sb.AppendLine();sb.AppendLine("// Warning LCD wrap columns (0 = disable wrapping)");sb.AppendLine("WARNING_WRAP_COLS = "+WARNING_WRAP_COLS);sb.AppendLine();sb.AppendLine("// Feature toggles (true/false)");sb.AppendLine("SORT_INVENTORY = "+SORT_INVENTORY);sb.AppendLine("MANAGE_REFINERIES = "+MANAGE_REFINERIES);sb.AppendLine("MANAGE_ASSEMBLERS = "+MANAGE_ASSEMBLERS);sb.AppendLine("USE_SURVIVALKIT_AS_ASSEMBLER = "+USE_SURVIVALKIT_AS_ASSEMBLER);sb.AppendLine("FORCE_AUTOCRAFTING = "+FORCE_AUTOCRAFTING);sb.AppendLine();sb.AppendLine("// Container behavior");sb.AppendLine("URANIUM_SEPARATE_CONTAINER = "+URANIUM_SEPARATE_CONTAINER);sb.AppendLine("TOOLS_FOOD_BOTTLE_SAME_CARGO = "+TOOLS_FOOD_BOTTLE_SAME_CARGO);sb.AppendLine("WEAPONS_AMMO_SAME_CARGO = "+WEAPONS_AMMO_SAME_CARGO);sb.AppendLine("INCLUDE_SUBGRIDS = "+INCLUDE_SUBGRIDS);sb.AppendLine("CLEAN_PRODUCTION_BLOCKS = "+CLEAN_PRODUCTION_BLOCKS);sb.AppendLine("AUTO_TAG_CONTAINERS = "+AUTO_TAG_CONTAINERS);sb.AppendLine("USE_SMALL_CARGO_OVERFLOW = "+USE_SMALL_CARGO_OVERFLOW);sb.AppendLine("REACTOR_REMOVE_EXCESS = "+REACTOR_REMOVE_EXCESS);sb.AppendLine("MANAGE_SAFE_ZONE = "+MANAGE_SAFE_ZONE);sb.AppendLine();sb.AppendLine("// Reactor uranium targets (kg)");sb.AppendLine("URANIUM_LARGE_GRID_LARGE = "+URANIUM_LARGE_GRID_LARGE);sb.AppendLine("URANIUM_LARGE_GRID_SMALL = "+URANIUM_LARGE_GRID_SMALL);sb.AppendLine("URANIUM_SMALL_GRID_LARGE = "+URANIUM_SMALL_GRID_LARGE);sb.AppendLine("URANIUM_SMALL_GRID_SMALL = "+URANIUM_SMALL_GRID_SMALL);sb.AppendLine();sb.AppendLine("// Block-specific tags go here (for containers, assemblers, etc.)");sb.AppendLine("// Example:");sb.AppendLine("// [Ore][Iron,Nickel]");sb.AppendLine("// [LOCK]");sb.AppendLine("// [AUTOCRAFT=1]");sb.AppendLine(MIM_DATA_END);return sb.ToString();}